Question 9
What is output by the code to the right? 
A)  XYQ61 
B)  XZQ61 
C)  WXYQ63 
D)  XZ71 
E)  XZQ71 

int a = 7, b = 2, c = 0; 
String r = ""; 

switch (a % 3 + b) { 
    case 4: r += "W"; c = 2; 
    case 3: r += "X"; 
        if (c++ > 0 && --a > 5) 
            r += "Y"; 
        else 
            r += "Z"; 
    case 2: r += "Q"; break; 
    default: r += "R"; 
} 
out.println(r + a + c); 

