int[] a = {1, 4, 2, 8, 3}; 
int[] b = a; 
int[] c = new int[a.length]; 

for (int i = 0; i < a.length - 1; i++) 
    c[i] = a[i + 1] - a[i]; 

b = c; 
a[0] += b[0] + c[0]; 
b[0] = 0; 

out.println(a[0] + "" + b[0] +  
        c[0] + a[1]); 
