Question 37
What does the method mysteryFunc1() to the right 
compute? 
A)  The sum of all elements in nums. 
B)  The maximum element in nums. 
C)  The maximum subarray sum of nums. 
D)  The longest increasing subsequence in nums. 
E)  A needlessly complicated way of returning the first element  

in nums. 
private static class Tuple { 
    int a, b, c, d; 
} 

private Tuple helper1(int[] arr, int l, int h) { 
    if (l == h) { 
        int val = arr[l]; 
        Tuple res = new Tuple(); 
        res.a = res.b = res.c = res.d = val; 
        return res; 
    } 

    int m = (l + h) / 2; 
    Tuple L = helper1(arr, l, m); 
    Tuple R = helper1(arr, m + 1, h); 
    return helper2(L, R); 
} 

private Tuple helper2(Tuple L, Tuple R) { 
    Tuple res = new Tuple(); 
    res.a = L.a + R.a; 
    res.b = Math.max(L.b, L.a + R.b); 
    res.c = Math.max(R.c, L.c + R.a); 
    res.d = Math.max(Math.max(L.d, R.d), 
                        L.c + R.b); 
    return res; 
} 

public int mysteryFunc1(int[] nums) { 
    if (nums.length == 0) return 0; 
    return helper1(nums, 0, nums.length - 1).d; 
}
